using System.IO.Compression;
using System.Text;

namespace Biotech.Net.Genomics.Tests;

/// <summary>
/// Access to the fixtures in data/hts (generated by gen_hts_fixtures.py with samtools/htslib 1.24) and
/// data/hts-specs (the GA4GH hts-specs conformance files).
/// </summary>
internal static class HtsFixtures
{
    public static string Hts(string name) => Path.Combine(AppContext.BaseDirectory, "data", "hts", name);

    public static string Spec(string name) => Path.Combine(AppContext.BaseDirectory, "data", "hts-specs", name);

    /// <summary>Reads a (possibly gzipped) text file.</summary>
    public static string ReadText(string path)
    {
        using var fs = File.OpenRead(path);
        Stream s = fs;
        if (path.EndsWith(".gz", StringComparison.Ordinal)) s = new GZipStream(fs, CompressionMode.Decompress);
        using var r = new StreamReader(s, Encoding.UTF8);
        return r.ReadToEnd();
    }

    /// <summary>The header lines and record lines of a SAM text produced by <c>samtools view -h</c>.</summary>
    public static (List<string> Header, List<string> Records) ReadSam(string path)
    {
        var header = new List<string>();
        var records = new List<string>();
        foreach (var line in ReadText(path).Split('\n'))
        {
            if (line.Length == 0) continue;
            (line[0] == '@' ? header : records).Add(line);
        }
        return (header, records);
    }

    /// <summary>Region query expectations: "## region" lines followed by the first four columns of each hit.</summary>
    public static List<(string Region, List<string> Lines)> ReadRegions(string path)
    {
        var result = new List<(string, List<string>)>();
        foreach (var line in File.ReadAllLines(path))
        {
            if (line.StartsWith("## ", StringComparison.Ordinal)) result.Add((line[3..], []));
            else if (line.Length > 0) result[^1].Item2.Add(line);
        }
        return result;
    }

    /// <summary>The first <paramref name="n"/> tab-separated columns.</summary>
    public static string Columns(string line, int n = 4) => string.Join('\t', line.Split('\t').Take(n));

    /// <summary>The fully decompressed bytes of a BGZF/gzip file (via the framework's GZipStream).</summary>
    public static byte[] Gunzip(byte[] data)
    {
        using var gz = new GZipStream(new MemoryStream(data), CompressionMode.Decompress);
        using var ms = new MemoryStream();
        gz.CopyTo(ms);
        return ms.ToArray();
    }

    /// <summary>Splits decompressed BAM bytes into the header part and the raw records (with their length prefix).</summary>
    public static (byte[] Header, List<byte[]> Records) SplitBam(byte[] bam)
    {
        int p = 4;
        int lText = BitConverter.ToInt32(bam, p); p += 4 + lText;
        int nRef = BitConverter.ToInt32(bam, p); p += 4;
        for (int i = 0; i < nRef; i++) { int l = BitConverter.ToInt32(bam, p); p += 4 + l + 4; }
        var header = bam[..p];
        var recs = new List<byte[]>();
        while (p < bam.Length)
        {
            int size = BitConverter.ToInt32(bam, p);
            recs.Add(bam[p..(p + 4 + size)]);
            p += 4 + size;
        }
        return (header, recs);
    }
}
